import{z as o,x as s,o as A,c as d,q as t,j as r,D as a,d as B,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"能源转型经济学","description":"","frontmatter":{"title":"能源转型经济学","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/env-energy-transition.md","filePath":"econ/env-energy-transition.md","lastUpdated":1791413859000}'),p={name:"econ/env-energy-transition.md"};function C(D,E,m,c,h,_){const n=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="能源转型经济学" tabindex="-1">能源转型经济学 <a class="header-anchor" href="#能源转型经济学" aria-label="Permalink to &quot;能源转型经济学&quot;">​</a></h1><div class="epigraph"><p>减排成本曲线不是常数：装机每翻一番，成本沿一条幂律下落——转型买的不是当期减排，是一条会移动的曲线。</p><footer>—— 据 Wright, Journal of the Aeronautical Sciences, 1936 与学习曲线文献整理</footer></div><p><a href="/econ/env-ets-deep">上一课</a>把帽子的稀缺性做可信、把价格稳进区间；但整套数量工具都在替一条给定的 MAC 收盘，它假定减排成本不随政策变。本课的核心事实是 MAC 会动：清洁技术成本随累计经验沿学习曲线下落，光伏组件学习率约两成，2010—2020 年组件价格下降约九成。碳价与学习曲线的相对速度，决定转型是「政策逼出来的永久成本」还是「政策启动后自续的过程」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态庇古逻辑里减排是纯成本，最优碳价等于边际损害。若减排成本本身随累计装机下降，早期减排买到的不只是当期损害减少，还有未来成本曲线的下移——静态最优不再是动态最优。缺口有两层。其一，知识外溢：干中学的收益大半落在对手与后来者身上，私人学习激励小于社会最优，市场自发走得太慢。其二，长期资产的不可逆与政策不确定互相放大：电站寿命几十年，碳价路径不稳，绿灰两侧的投资都加装风险溢价——灰资产怕搁浅，绿资产怕退坡，谁都不敢先动。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>学习曲线写成 \\(C(X)=C_0\\,(X/X_0)^{-\\lambda}\\)，\\(X\\) 是累计装机，每翻一番成本降到 \\(2^{-\\lambda}\\)。政策含义有三。第一，最优路径是投资问题而非当期配置问题：早期单位成本高于化石，社会最优先亏后赚，跨期权衡要按整条路径算。第二，两个失灵配两个工具：碳价管排放外部性，学习政策管知识外部性；只给一个会错位——没有碳价的学习补贴是在错误的边上楔入（补贴课细说）。第三，平准化度电成本（LCOE）只算电厂自己的账：波动电源的备用、电网与消纳成本不在 LCOE 里，报价低不等于系统便宜，整合成本是下一课的题。</p><p><span class="marginnote">术语翻译：LCOE（平准化度电成本）是把建站到退役的全部花费按总发电量摊平后的「每度电账面成本」。它只算电厂自己的账：没风没太阳时的备用、电网与消纳的钱不在里面——组件报价低，不等于系统便宜。</span></p>',8)),(A(),r(l,null,{default:a(()=>[i(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CARBON%5B%22%E7%A2%B3%E4%BB%B7%3A%20%E6%8E%A8%E9%AB%98%E5%8C%96%E7%9F%B3%E6%88%90%E6%9C%AC%22%5D%20--%3E%20GAP%5B%22%E7%BB%BF%E7%81%B0%E6%88%90%E6%9C%AC%E5%B7%AE%22%5D%0A%20%20LEARN%5B%22%E5%AD%A6%E4%B9%A0%E6%9B%B2%E7%BA%BF%3A%20%E6%88%90%E6%9C%AC%E9%9A%8F%E7%B4%AF%E8%AE%A1%E8%A3%85%E6%9C%BA%E4%B8%8B%E8%90%BD%22%5D%20--%3E%20GAP%0A%20%20GAP%20--%3E%20EARLY%5B%22%E6%97%A9%E6%9C%9F%E6%8A%95%E5%85%A5%3A%20%E4%B9%B0%E6%9C%AA%E6%9D%A5%E7%9A%84%E4%BD%8E%E6%88%90%E6%9C%AC%22%5D%0A%20%20EARLY%20--%3E%20LOCK%5B%22%E5%8A%A8%E6%80%81%E9%80%92%E5%A2%9E%E6%94%B6%E7%9B%8A%3A%20%E8%BD%AC%E5%9E%8B%E8%87%AA%E7%BB%AD%22%5D%0A%20%20UNC%5B%22%E6%94%BF%E7%AD%96%E4%B8%8D%E7%A1%AE%E5%AE%9A%3A%20%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%20--%3E%20EARLY%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"学习使干预自续的机制是动态递增收益：成本是累计经验的函数，政策性需求转化为经验，把曲线上任意起点之后的未来成本永久压低——先发优势变成路径依赖，临时政策足以把系统从一个均衡推到另一个。这是上一课「承诺机制」的反面：帽子靠规则防松，学习靠规则防退。政策不确定为什么同时冻住两侧：资产不可逆使「再等一年」有期权价值，波动越大越值得等；转型的期权逻辑在气候金融课还会以资本成本的面目回来。搁浅资产是同一枚硬币的反面：碳预算约束意味着已探明化石储备的一部分永远不能烧，账面价值与使用约束之差要有人减记——这一笔在金融课变成系统风险。",-1)),(A(),r(l,null,{default:a(()=>[i(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E6%94%BF%E7%AD%96%E8%B7%AF%E5%BE%84%E4%B8%8D%E7%A1%AE%E5%AE%9A%22%5D%20--%3E%20OPT%5B%22%E8%B5%84%E4%BA%A7%E4%B8%8D%E5%8F%AF%E9%80%86%EF%BC%9A%E3%80%8C%E5%86%8D%E7%AD%89%E4%B8%80%E5%B9%B4%E3%80%8D%E6%9C%89%E6%9C%9F%E6%9D%83%E4%BB%B7%E5%80%BC%22%5D%0A%20%20OPT%20--%3E%20GREEN%5B%22%E7%BB%BF%E8%B5%84%E4%BA%A7%E6%80%95%E8%A1%A5%E8%B4%B4%E9%80%80%E5%9D%A1%20%E2%86%92%20%E6%8A%BC%E5%90%8E%E6%8A%95%E8%B5%84%22%5D%0A%20%20OPT%20--%3E%20GREY%5B%22%E7%81%B0%E8%B5%84%E4%BA%A7%E6%80%95%E7%A2%B3%E4%BB%B7%E8%B5%B0%E9%AB%98%E3%80%81%E6%90%81%E6%B5%85%20%E2%86%92%20%E6%8A%BC%E5%90%8E%E6%8A%95%E8%B5%84%22%5D%0A%20%20GREEN%20--%3E%20FREEZE%5B%22%E5%8F%8C%E4%BE%A7%E8%A7%82%E6%9C%9B%EF%BC%9A%E8%BD%AC%E5%9E%8B%E5%86%BB%E5%9C%A8%E5%8D%8A%E8%B7%AF%22%5D%0A%20%20GREY%20--%3E%20FREEZE%0A%20%20U%20--%3E%20SPILL%5B%22%E9%A2%84%E6%9C%9F%E6%9C%AA%E6%9D%A5%E7%A2%B3%E4%BB%B7%E6%9B%B4%E9%AB%98%20%E2%86%92%20%E8%B5%84%E6%BA%90%E4%B8%BB%E4%BA%BA%E5%8A%A0%E9%80%9F%E5%BC%80%E9%87%87%EF%BC%88%E7%BB%BF%E8%89%B2%E6%82%96%E8%AE%BA%EF%BC%89%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">学习率是最被低估的参数：光伏组件约 20%/翻倍，据此 2010—2020 年组件价格下降约九成。「太贵」是关于累计装机的陈述，不是关于技术的终审判决。</span></p><p><span class="marginnote">数字实例：学习率 20% 意思是累计装机每翻一番、成本降到原来的八成。翻五个跟斗（装机 32 倍），成本约为起初的 \\(0.8^5 \\approx 0.33\\)——降到三分之一。所以「现在太贵」必须先问：现在累计装机是多少。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>学习曲线是经验规律不是定律：Wright 的口径来自飞机机身工时，外推到材料受限、土地受限的技术会失灵；曲线外推也会被电网与资源瓶颈截断——下一课的物理约束。绿色悖论提醒方向可能反向：预期未来碳价走高，资源主人的最优反应是当下加速开采（Sinn 2012）。补贴的退坡与寻租政治留到补贴课。本课不写确定性路线图：学习率外推是规划口径，任何「某年成本必然降到多少」的句子都该附带它的 \\(2^{-\\lambda}\\) 与不确定性。</p><p><span class="marginnote">常见误区：把学习曲线当成「某年成本必然降到多少」的物理定律。它是经验规律：材料涨价、土地受限、电网瓶颈都可能掐断下落；引用任何学习率，都要附带它的统计口径与不确定性区间。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>减排成本随累计经验下落：转型是动态问题，早期成本买的是曲线位移。</li><li>知识外溢使市场学得太慢：碳价与学习政策各治一个失灵，缺位会错位。</li><li>政策不确定抬高双侧期权价值，同时冻住灰绿投资；搁浅资产是同一约束的减记面。</li><li>LCOE 不是系统成本：整合成本是电力市场设计的入口。</li><li>学习率外推有边界：材料、土地、电网与绿色悖论都可能改写方向。</li><li>出处：Wright 1936；Sinn 2012；成本数据口径据行业统计整理。</li></ul>',7))])}const F=o(p,[["render",C]]);export{f as __pageData,F as default};
